 */
export interface McpHttpServer {
    /** 服务器唯一名(config key)。 */
    name: string;
    /** Streamable HTTP 端点(如 https://mem.example.com/mcp/)。 */
    url: string;
    /** 逐字写进每个请求的 HTTP 头(常用于 Authorization;可能含 secret,不进 manifest)。 */
    headers?: Readonly<globalThis.Record<string, string>>;
